insert into auth.users (id) values ('00000000-0000-0000-0000-0000000000aa') on conflict (id) do nothing;
insert into public.profiles (id, role, display_name, locale, is_active)
values ('00000000-0000-0000-0000-0000000000aa', 'curator', 'Seed Editor', 'ru', true)
on conflict (id) do nothing;

insert into public.guide_entries
	(id, category_slug, slug, title, summary, note, icon, language, status,
	 trust_badge, under_review_note, owner_profile_id, created_by_profile_id,
	 updated_by_profile_id, published_at, last_verified_at)
values
	('00000000-0000-0000-0000-000000000025', 'safety', 'safety-scam-exchange', 'Скам при обмене валют и крипты', 'Спросил в чате «где обменять?» - и тебе в личку пишет «проверенный обменник» или «поменяю сам». Это мошенник: блокируй сразу. Отзывы и скрины переводов - фейк. Честный обменник рекламируют в больших живых чатах, приезжают лично, не пишут первыми, у него заполнен профиль и канал с курсами.', 'Считай курс сам, не переводи деньги вперёд. В аэропорту курс невыгодный. Крипту - только P2P с выводом на местный счёт. С картами снимай в банкомате: VPBank не берёт комиссию.', 'i-lucide-alert-octagon', 'ru', 'published', 'under_review', 'Контент из knowledge-dump, ждёт проверки', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-000000000026', 'safety', 'safety-scam-exchange', 'Currency and crypto exchange scams', 'Ask in a chat "where to exchange?" - and a "trusted exchanger" or "I can swap it myself" DMs you. That is a scammer: block immediately. Reviews and transfer screenshots are fake. An honest exchanger advertises in big live chats, meets in person, never DMs first, and has a filled profile and a rates channel.', 'Count the rate yourself, never pay upfront. Airport rates are bad. For crypto use P2P with withdrawal to a local account. With cards, withdraw from ATMs: VPBank charges no fee.', 'i-lucide-alert-octagon', 'en', 'published', 'under_review', 'Knowledge-dump content, pending verification', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-000000000027', 'safety', 'safety-scam-jobs', 'Скам-работа и «красивые девушки»', 'Онлайн-работа «в крипте» с обучением и файлами - 100% скам: тебя уведут на сайт, где ты подпишешь смарт-контракт и спишут кошелёк. Реклама в Instagram/TikTok («зарабатывай на крипте», «изменю твою жизнь») - тот же развод. Аккаунт «красивой девушки» из Дананга, которая хочет пообщаться, разведёт на предоплату или «билет на событие». Никаких предоплат - вообще.', 'Увидели такой сценарий в чате - жалуйтесь администрации. Легальная удалённая работа никогда не требует вложений от тебя.', 'i-lucide-user-x', 'ru', 'published', 'under_review', 'Контент из knowledge-dump, ждёт проверки', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-000000000028', 'safety', 'safety-scam-jobs', 'Job scams and "pretty girls"', '"Crypto job" offers with training files are 100% scams: you get routed to a site where you sign a smart contract and your wallet is drained. Instagram/TikTok ads ("earn from crypto", "I will change your life") are the same play. A "pretty girl in Da Nang" account that wants to chat will extract a prepayment or an "event ticket". Never pay upfront - period.', 'See this scenario in a chat - report it to the admins. Legit remote work never asks you to invest.', 'i-lucide-user-x', 'en', 'published', 'under_review', 'Knowledge-dump content, pending verification', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-000000000029', 'safety', 'safety-scam-classifieds', 'Скам с предоплатой: жильё, визы, посылки', 'Красивое жильё, но «риэлтор» просит предоплату - почти всегда мошенники, всегда смотри жильё лично. «Сервис» оформления визы, которому ты отправил деньги и паспортные данные, исчезает. Попутчик предлагает передать посылку за предоплату - договорись об оплате при получении. Аккаунт с сотней «услуг» и неживых чатов в профиле - блокируй и жалуйся.', 'Общее правило: никакой предоплаты людям, которых не проверили. Проверенные сервисы рекламируются в живых экспатских чатах.', 'i-lucide-home', 'ru', 'published', 'under_review', 'Контент из knowledge-dump, ждёт проверки', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-00000000002a', 'safety', 'safety-scam-classifieds', 'Prepayment scams: rent, visas, parcels', 'Beautiful housing but the "realtor" wants a deposit upfront - almost always scammers; always view housing in person. A visa "service" that took your money and passport details disappears. A traveler offers to carry a parcel for prepayment - agree on payment on delivery instead. An account with a hundred "services" and dead chats in its profile - block and report.', 'General rule: no prepayments to unverified people. Trusted services advertise in live expat chats.', 'i-lucide-home', 'en', 'published', 'under_review', 'Knowledge-dump content, pending verification', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-00000000002b', 'money', 'money-sim-internet', 'Симка и интернет', 'Симку лучше покупать в салонах связи - гарантия стабильной работы; в аэропорту или у уличных продавцов симка может в любой момент перестать работать. Подойдёт и e-SIM. Топ-операторы: Viettel, Mobifone, Vinaphone; худший - Vietnamobile. Тариф ~150 тыс. ₫/мес за 5-6 ГБ в день, безлимитов нет, покрытие ловит даже между городами. Домашний интернет подключают через менеджера здания: Viettel и FPT.', 'Скорость интернета в городе хорошая; для долгой жизни домашний интернет + байк-тариф на телефоне - стандартный набор.', 'i-lucide-sim-card', 'ru', 'published', 'under_review', 'Контент из knowledge-dump, ждёт проверки', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-00000000002c', 'money', 'money-sim-internet', 'SIM and internet', 'Buy a SIM at a phone store - guaranteed stable service; airport and street-seller SIMs can die any moment. An e-SIM also works. Top operators: Viettel, Mobifone, Vinaphone; the worst is Vietnamobile. A typical plan is ~150k VND/month for 5-6 GB/day, no unlimited plans, coverage works even between cities. Home internet is arranged through the building manager: Viettel and FPT.', 'City internet speeds are good; for long-term living home internet plus a phone data plan is the standard setup.', 'i-lucide-sim-card', 'en', 'published', 'under_review', 'Knowledge-dump content, pending verification', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-00000000002d', 'transport', 'transport-license', 'Езда без прав: закон', 'Байки свыше 50cc (и электробайки свыше 4 кВт) требуют международного водительского удостоверения (МВУ). Без прав легально: скутеры до 50cc и электробайки до 4 кВт - например VinFast.', 'МВУ делается дома до поездки - национальные права во Вьетнаме не работают.', 'i-lucide-id-card', 'ru', 'published', 'under_review', 'Контент из knowledge-dump, ждёт проверки', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-00000000002e', 'transport', 'transport-license', 'Riding without a license: the law', 'Bikes over 50cc (and e-bikes over 4 kW) require an International Driving Permit (IDP). Without a license you can legally ride scooters under 50cc and e-bikes under 4 kW - for example VinFast.', 'Get the IDP at home before the trip - national licenses alone are not valid in Vietnam.', 'i-lucide-id-card', 'en', 'published', 'under_review', 'Knowledge-dump content, pending verification', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-00000000002f', 'transport', 'transport-bike', 'Аренда байка', 'Ищи по Google Maps «Cho Thue Xe May» (аренда байков) или Morobike Rental; иногда байки сдают отели. Новые и свежие байки дороже. Популярные модели: Honda Air Blade, Yamaha Nouvo - от 1,8 млн ₫/мес; Yamaha NVX, Honda PCX - от 2 млн ₫/мес. Электробайки VinFast ~1,8 млн ₫/мес и не требуют прав. Краткосрочно: 100-180 тыс. ₫/день.', 'Депозит 1-3 млн ₫ или паспорт. Проверь тормоза и свет, сфотографируй царапины до подписания. Рекомендации из экспат-чатов: https://maps.app.goo.gl/yVjokSMD1denj2568 | https://maps.app.goo.gl/JDmfTokvvVMxNeeV7', 'i-lucide-bike', 'ru', 'published', 'under_review', 'Обновлено из knowledge-dump', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now()),
	('00000000-0000-0000-0000-000000000030', 'transport', 'transport-bike', 'Bike rental', 'Search Google Maps for "Cho Thue Xe May" (bike rental) or Morobike Rental; hotels sometimes rent bikes too. Newer bikes cost more. Popular models: Honda Air Blade, Yamaha Nouvo - from 1.8M VND/month; Yamaha NVX, Honda PCX - from 2M VND/month. VinFast electric bikes ~1.8M VND/month and need no license. Short-term: 100-180k VND/day.', 'Deposit 1-3M VND or your passport. Check brakes and lights, photograph scratches before signing. Expat-chat recommendations: https://maps.app.goo.gl/yVjokSMD1denj2568 | https://maps.app.goo.gl/JDmfTokvvVMxNeeV7', 'i-lucide-bike', 'en', 'published', 'under_review', 'Updated from knowledge-dump', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', '00000000-0000-0000-0000-0000000000aa', now(), now())
on conflict (category_slug, slug, language) do update
set title = excluded.title, summary = excluded.summary, note = excluded.note,
	updated_at = now(), last_verified_at = now();
